import { useState } from "react";
import { Download, Trash2, History, FileText } from "lucide-react";
import { useDocuments, useDeleteDocument, useDownloadDocument } from "@/hooks/useDocuments";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { DocumentVersions } from "./DocumentVersions";
import type { Document } from "@/types/api";

const CATEGORIES = ["Drawing", "Specification", "Approval", "Photo", "Test Report", "Contract", "Other"];

function formatBytes(bytes: number | null): string {
  if (!bytes) return "—";
  const mb = bytes / (1024 * 1024);
  if (mb >= 1) return `${mb.toFixed(1)} MB`;
  const kb = bytes / 1024;
  return `${kb.toFixed(0)} KB`;
}

function formatDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

interface DocumentListProps {
  projectId: string;
}

export function DocumentList({ projectId }: DocumentListProps) {
  const [category, setCategory] = useState<string>("");
  const [versionsDoc, setVersionsDoc] = useState<Document | null>(null);

  const { data, isLoading } = useDocuments(projectId, category || undefined);
  const deleteMutation = useDeleteDocument();
  const downloadMutation = useDownloadDocument();

  const groupedDocs = (data?.items ?? []).reduce<Record<string, Document[]>>((acc, doc) => {
    const cat = doc.category || "Other";
    if (!acc[cat]) acc[cat] = [];
    acc[cat].push(doc);
    return acc;
  }, {});

  const handleDelete = async (doc: Document) => {
    if (window.confirm(`Delete "${doc.original_name}"?`)) {
      await deleteMutation.mutateAsync({ projectId, documentId: doc.id });
    }
  };

  const handleDownload = async (doc: Document) => {
    await downloadMutation.mutateAsync({ documentId: doc.id, filename: doc.original_name });
  };

  if (isLoading) {
    return <div className="p-4 text-center text-muted-foreground">Loading documents...</div>;
  }

  if (!data?.items.length && !category) {
    return (
      <Card>
        <CardContent className="flex flex-col items-center justify-center py-12 text-center">
          <FileText className="h-12 w-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground mb-4">No documents uploaded yet</p>
          <p className="text-sm text-muted-foreground">Use the upload form to add documents to this project</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Select value={category} onValueChange={setCategory}>
          <SelectTrigger className="w-48">
            <SelectValue placeholder="All categories" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">All categories</SelectItem>
            {CATEGORIES.map((cat) => (
              <SelectItem key={cat} value={cat}>{cat}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        {category && (
          <Button variant="ghost" size="sm" onClick={() => setCategory("")}>
            Clear filter
          </Button>
        )}
      </div>

      {Object.entries(groupedDocs).map(([cat, docs]) => (
        <Card key={cat}>
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-base font-semibold">{cat}</CardTitle>
              <Badge variant="secondary">{docs.length}</Badge>
            </div>
          </CardHeader>
          <CardContent className="p-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Version</TableHead>
                  <TableHead>Size</TableHead>
                  <TableHead>Uploaded</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {docs.map((doc) => (
                  <TableRow key={doc.id}>
                    <TableCell className="font-medium">{doc.original_name}</TableCell>
                    <TableCell>
                      <Badge variant="outline">v{doc.version}</Badge>
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {formatBytes(doc.size_bytes)}
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {formatDate(doc.uploaded_at)}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-1">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => setVersionsDoc(doc)}
                          title="Version history"
                        >
                          <History className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleDownload(doc)}
                          title="Download"
                        >
                          <Download className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleDelete(doc)}
                          title="Delete"
                          className="text-destructive hover:text-destructive"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      ))}

      <DocumentVersions
        document={versionsDoc}
        onClose={() => setVersionsDoc(null)}
      />
    </div>
  );
}

import { useState } from "react";
import { Upload, AlertCircle } from "lucide-react";
import { useUploadDocument } from "@/hooks/useDocuments";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const CATEGORIES = ["Drawing", "Specification", "Approval", "Photo", "Test Report", "Contract", "Other"];

const MAX_FILE_SIZE = 50 * 1024 * 1024;

interface DocumentUploadProps {
  projectId: string;
}

export function DocumentUpload({ projectId }: DocumentUploadProps) {
  const [file, setFile] = useState<File | null>(null);
  const [category, setCategory] = useState<string>("Drawing");
  const [error, setError] = useState<string>("");

  const uploadMutation = useUploadDocument();

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setError("");
    const selected = e.target.files?.[0];
    if (!selected) return;
    if (selected.size > MAX_FILE_SIZE) {
      setError(`File exceeds 50MB limit (${(selected.size / (1024 * 1024)).toFixed(1)} MB)`);
      setFile(null);
      return;
    }
    setFile(selected);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    setError("");
    try {
      await uploadMutation.mutateAsync({ projectId, file, category });
      setFile(null);
    } catch {
      setError("Upload failed. Please try again.");
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Upload Document</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="doc-file">File</Label>
            <input
              id="doc-file"
              type="file"
              accept=".pdf,.dwg,.docx,.xlsx,.png,.jpg,.jpeg"
              onChange={handleFileChange}
              className="w-full text-sm file:mr-4 file:py-2 file:px-4 file:rounded file:border file:border-input file:text-sm file:font-medium file:bg-secondary hover:file:bg-secondary/80"
            />
            {file && (
              <p className="text-sm text-muted-foreground">
                Selected: {file.name} ({(file.size / (1024 * 1024)).toFixed(1)} MB)
              </p>
            )}
          </div>
          <div className="space-y-2">
            <Label htmlFor="doc-category">Category</Label>
            <Select value={category} onValueChange={setCategory}>
              <SelectTrigger id="doc-category">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CATEGORIES.map((cat) => (
                  <SelectItem key={cat} value={cat}>{cat}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          {error && (
            <div className="flex items-center gap-2 text-sm text-destructive">
              <AlertCircle className="h-4 w-4" />
              {error}
            </div>
          )}
          <Button
            type="submit"
            disabled={!file || uploadMutation.isPending}
            className="w-full"
          >
            {uploadMutation.isPending ? (
              <>
                <Upload className="h-4 w-4 mr-2 animate-pulse" />
                Uploading...
              </>
            ) : (
              <>
                <Upload className="h-4 w-4 mr-2" />
                Upload Document
              </>
            )}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

import { Download } from "lucide-react";
import { useDocumentVersions, useDownloadDocument } from "@/hooks/useDocuments";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import type { Document } from "@/types/api";

interface DocumentVersionsProps {
  document: Document | null;
  onClose: () => void;
}

function formatDate(dateStr: string): string {
  return new Date(dateStr).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function DocumentVersions({ document, onClose }: DocumentVersionsProps) {
  const { data: versions, isLoading } = useDocumentVersions(document?.id ?? "");
  const downloadMutation = useDownloadDocument();

  const handleDownload = async (docId: string, filename: string) => {
    await downloadMutation.mutateAsync({ documentId: docId, filename });
  };

  return (
    <Dialog open={!!document} onOpenChange={() => onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Version History</DialogTitle>
        </DialogHeader>
        {isLoading ? (
          <div className="py-8 text-center text-muted-foreground">Loading...</div>
        ) : !versions?.length ? (
          <div className="py-8 text-center text-muted-foreground">No versions found</div>
        ) : (
          <div className="space-y-3">
            {versions.map((v) => (
              <div
                key={v.id}
                className="flex items-center justify-between rounded-lg border p-3"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <Badge variant="outline">v{v.version}</Badge>
                    <span className="text-sm font-medium">{v.original_name}</span>
                  </div>
                  <div className="text-xs text-muted-foreground">
                    <span>{v.category}</span>
                    <span className="mx-2">·</span>
                    <span>{formatDate(v.uploaded_at)}</span>
                    {v.uploaded_by && (
                      <>
                        <span className="mx-2">·</span>
                        <span>{v.uploaded_by}</span>
                      </>
                    )}
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => handleDownload(v.id, v.original_name)}
                >
                  <Download className="h-4 w-4" />
                </Button>
              </div>
            ))}
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

